// =============================================================================
// HALCYON REACH - content/codex.js  (WORLD-B)
// Pure data. CODEX = [ { id, title, category, text, unlockedBy } ]
//
// category: 'species' | 'place' | 'phenomenon' | 'history' | 'tech'
// unlockedBy (exactly one key, or null = known from the start):
//   'event'                          - granted by an event/mission fx {codex:id} (or mission reward.codex)
//   { scan: 'planetType:ice' }       - first scanPlanet of a planet of that type   (also 'feature:ruins')
//   { phenomenon: 'pulsar' }         - first investigate()/arrival with that phenomenon in the system
//   { star: 'neutron' }              - first visit to a system with that star type
//   { faction: 'vesperine' }         - first contact (hail / dock / event with that faction)
//   { visit: 'story_id' }            - first arrival at that story system
//   { flag: 'name' }                 - when that flag becomes set
//   { mission: 'missionId' }         - when that mission is completed
// ENGINE: unlocking emits 'discovery' {kind:'codex', id, text}. Event-granted ids are covered below, header-matched
// to src/content/events/*.js CODEX: comments (ids "codex_*", plus aurora_life and lantern_question aliases).
// =============================================================================

export const CODEX = [
  // ---------------------------------------------------------------- SPECIES / FACTIONS
  { id: 'concord_of_lyra', title: 'The Concord of Lyra', category: 'species', unlockedBy: { faction: 'concord' },
    text: 'Terran-descended settlers who believe any problem can be solved with a committee, a form and a really good biscuit. They are, against all odds, usually right.' },
  { id: 'quillari_clans', title: 'The Quillari Clans', category: 'species', unlockedBy: { faction: 'quillari' },
    text: 'Feathered free-traders who treat haggling as conversation and conversation as hospitality. Their ships are loud, their tables are generous, and every price is a negotiating opener.' },
  { id: 'vesperine_choirs', title: 'The Vesperine Choirs', category: 'species', unlockedBy: { faction: 'vesperine' },
    text: 'Crystalline beings who speak in harmonics and build their cities out of sustained chords. They dislike loud noises and slammed doors, and they forgive almost everything else.' },
  { id: 'archivist_librarians', title: 'The Archivists', category: 'species', unlockedBy: { faction: 'archivists' },
    text: 'Ancient machine librarians who answer exactly the question asked. They are scrupulously polite and hoard unanswered questions the way dragons hoard gold.' },
  { id: 'drifter_fleets', title: 'The Drifter Fleets', category: 'species', unlockedBy: { faction: 'drifters' },
    text: 'Nomad habitat-fleets whose craftspeople weave, mend and tell stories as the long hulls drift between stars. They distrust "chartered" folk until you have shared a meal.' },
  { id: 'halcyon_robot', title: 'Mendel the Maintenance Bot', category: 'species', unlockedBy: null,
    text: 'Halcyon\'s maintenance robot, a squat brass box on treads with three arms and a deep fondness for oil cans. It hums when content, which is most of the time.' },
  { id: 'meridian_society', title: 'The Meridian Society for Open Skies', category: 'history', unlockedBy: null,
    text: 'An unarmed, charitable society of cartographers, relief workers and interpreters, founded on the principle that the sky belongs to everyone. Its motto is "Say please, and bring tea".' },
  { id: 'aurora_life', title: 'Aurora-Life', category: 'species', unlockedBy: 'event',
    text: 'Gossamer ribbons of charged gas that flicker with something very like thought. They answer light with light, and shy away from loud engines.' },
  { id: 'codex_aurora_beings', title: 'The Aurora-Beings', category: 'species', unlockedBy: 'event',
    text: 'Spacefaring auroras who drift along magnetic currents, composing slow light-poems over centuries. They seem to be the most patient poets in the galaxy.' },
  { id: 'codex_lighthouse_robot', title: 'The Lone Keeper Robot', category: 'species', unlockedBy: 'event',
    text: 'A dutiful maintenance machine still tending a long-abandoned beacon, polishing the lens daily for visitors who might one day arrive. It is overjoyed that you did.' },
  { id: 'codex_kelp_cities', title: 'Tidewright Kelp Cities', category: 'species', unlockedBy: 'event',
    text: 'Floating cities woven by gentle sea-folk from living kelp, which sway with the tide and hum in contentment. Visitors are greeted with warm broth and a rope ladder.' },
  { id: 'codex_lava_forgers', title: 'The Forge-Hospitality of Molten Worlds', category: 'species', unlockedBy: 'event',
    text: 'Heat-loving forge-folk who offer guests the highest honour of their culture: a cup of tea brewed over a live lava vent. Wear sensible shoes and say thank you twice.' },
  { id: 'codex_crystal_gardens', title: 'Crystal Gardens and Their Gardeners', category: 'species', unlockedBy: 'event',
    text: 'Vesperine gardeners who grow crystals in slow, intricate patterns, humming to coax them along. Each garden is a song played over centuries.' },
  { id: 'codex_polite_flora', title: 'Courteous Flora', category: 'species', unlockedBy: 'event',
    text: 'Plants that return a greeting, by dipping their leaves or releasing a gentle scent. Botanists agree they are not intelligent, and the plants do not argue.' },
  { id: 'codex_miner_coops', title: 'Asteroid Mining Cooperatives', category: 'species', unlockedBy: 'event',
    text: 'Friendly cooperatives of miners who work the belts in tight rotating shifts, trading ore for gossip. A mining coop will always find room for one more at the lunch table.' },

  // ---------------------------------------------------------------- PLACES
  { id: 'the_gate', title: 'The Gate', category: 'place', unlockedBy: null,
    text: 'A stable wormhole ring found at the edge of Concord space, polished by travel and gently humming. Through it lies the Lantern Reach: warm light and no one shouting.' },
  { id: 'gate_anchorage', title: 'Gate Anchorage', category: 'place', unlockedBy: { visit: 'gate_anchorage' },
    text: 'The first Meridian anchorage beyond the Gate, a sunny little harbour of buoys and bustling clerks. It has a tea shop, a notice board, and a very proud flag.' },
  { id: 'lyra_museum', title: 'The Lyra Landing Museum', category: 'place', unlockedBy: 'event',
    text: 'A small museum with a very large ambition: to display Interesting Things From The Reach. The first case is empty, but the curator has high hopes.' },
  { id: 'pennywhistle_bazaar', title: 'The Grand Pennywhistle Bazaar', category: 'place', unlockedBy: { visit: 'pennywhistle' },
    text: 'The beating heart of the Shoals: four hundred stalls under two suns, and a complaints box nobody has ever emptied. It is the best place in the galaxy to buy a hat.' },
  { id: 'quillari_markets', title: 'Quillari Markets', category: 'place', unlockedBy: 'event',
    text: 'Markets where prices float with mood, weather and the quality of the gossip. Visitors are always offered tea first, and a better price second.' },
  { id: 'hollin_sniffle', title: 'Hollin\'s Rest', category: 'place', unlockedBy: 'event',
    text: 'A small colony known mainly for its soup, its damp air, and its annual Great Sniffle. A parcel of medical kits is the nicest gift you can give it.' },
  { id: 'cantabile_hall', title: 'Cantabile', category: 'place', unlockedBy: { visit: 'cantabile' },
    text: 'A blue-lit Vesperine city drawn out of a single sustained chord. Every doorway has a pitch, and every guest is politely asked to arrive in tune.' },
  { id: 'hollow_archive', title: 'The Hollow Archive', category: 'place', unlockedBy: 'event',
    text: 'A cluster of cold stars whose moons are shelves and whose planets are reading rooms. Its librarians have kept every question ever asked, in alphabetical order.' },
  { id: 'long_table', title: 'The Long Table', category: 'place', unlockedBy: { visit: 'long_table' },
    text: 'Forty drifter habitats lashed together into one enormous communal feast. By tradition, the guest tells the first story and washes the last dish.' },
  { id: 'brightwater_light', title: 'Brightwater Light', category: 'place', unlockedBy: { visit: 'lantern_brightwater' },
    text: 'A drowned moon wearing a ribbon of gold light, home to the second Lantern. Quillari pilgrims leave small gifts at its dock, strictly in secret.' },
  { id: 'last_taper', title: 'Last Taper', category: 'place', unlockedBy: { visit: 'lantern_taper' },
    text: 'A candle-bright Lantern keeping vigil beside a sleeping black hole. Drifter tales say it is the oldest light in the Reach and the last one anyone will see.' },
  { id: 'probe_seven', title: 'Probe 7', category: 'history', unlockedBy: 'event',
    text: 'A Meridian weather probe that went on a three-day mission and never came home. It is still transmitting forecasts, with great enthusiasm, to nobody in particular.' },
  { id: 'codex_wedding_ship', title: 'The Wedding Ship Evensong', category: 'place', unlockedBy: 'event',
    text: 'A drifting ship frozen mid-celebration, with chandeliers still lit and cake still on the plates. Whoever was married aboard left in such a hurry they forgot the cake.' },
  { id: 'codex_caravan_roads', title: 'Dust-Road Caravans of the Vanished', category: 'place', unlockedBy: 'event',
    text: 'Wind-scoured desert trails marked by painted wagons and cairns of stacked stones. Whoever drove these caravans left a map on the last wagon and a note: "Come when you\'re ready."' },
  { id: 'codex_tea_clouds', title: 'Tea-Clouds of the Toxic Worlds', category: 'place', unlockedBy: 'event',
    text: 'Poisonous clouds that, drifted through a filter, make a surprisingly fine brew. Do not drink it raw. Do not ask what is in it.' },
  { id: 'codex_polite_doors', title: 'Doors That Must Be Asked Nicely', category: 'place', unlockedBy: 'event',
    text: 'Ancient vault doors that open only to a polite request, which is fine unless you have a deadline. They are, on balance, the most civilised security measure ever devised.' },
  { id: 'codex_ghost_logs', title: 'Derelict Ghost-Logs', category: 'history', unlockedBy: 'event',
    text: 'Fragments of ship logs that replay themselves in empty hulls, never quite finishing their last sentence. Cleaning them up respectfully is considered good manners.' },

  // ---------------------------------------------------------------- PHENOMENA
  { id: 'the_lanterns', title: 'The Lanterns', category: 'phenomenon', unlockedBy: { phenomenon: 'beacon' },
    text: 'Five (that we know of) glass-and-light beacons scattered across the Reach. They glow without fuel, answer hails in patterns of light, and appear to have been left on deliberately.' },
  { id: 'codex_lantern_first', title: 'The First Lantern: a Greeting', category: 'phenomenon', unlockedBy: 'event',
    text: 'At Wickhaven, the first Lantern greeted our hail with a pattern that repeats three times: a handshake, a welcome, and a small flourish. It is the most polite beacon in the galaxy.' },
  { id: 'codex_lantern_question', title: 'The Lantern\'s Question', category: 'phenomenon', unlockedBy: 'event',
    text: 'The second Lantern projects not an answer but a question: "Where are you going, and have you eaten?" In all known languages, this is a kindness.' },
  { id: 'lantern_question', title: 'A Question in the Light', category: 'phenomenon', unlockedBy: 'event',
    text: 'Each Lantern asks a gentle question and waits, possibly for centuries, for an answer. None of the questions are tests.' },
  { id: 'codex_lantern_memory', title: 'What the Lanterns Remember', category: 'phenomenon', unlockedBy: 'event',
    text: 'The third Lantern stores memories of every visitor in a slow, spiralling glow. Those who came before are still there, a little faded, still waving.' },
  { id: 'codex_lantern_voices', title: 'The Voices in the Light', category: 'phenomenon', unlockedBy: 'event',
    text: 'The fourth Lantern sings in many voices at once, a choir of travellers who passed through ages ago. They all say, in slightly different keys, "Welcome. Come in."' },
  { id: 'codex_lantern_invite', title: 'The Lantern Invitation', category: 'phenomenon', unlockedBy: 'event',
    text: 'The fifth Lantern is not a beacon but a doorway, open to anyone who answers kindly. Its invitation is simple: stay as long as you like, and leave it as you found it, or better.' },
  { id: 'open_sky_fellowship', title: 'The Open Sky Fellowship', category: 'history', unlockedBy: 'event',
    text: 'An elder fleet of cartographers, interpreters and relief workers who surveyed the Reach long before the Gate was found. They lit the Lanterns as welcome-mats for whoever came next, and then, gently, went on.' },
  { id: 'fellowship_tokens', title: 'Fellowship Tokens', category: 'history', unlockedBy: 'event',
    text: 'Small blue discs stamped with an open eye and a lamp, issued to every member of the Fellowship. The oldest membership cards in the galaxy; they hum when brought near a Lantern.' },
  { id: 'welcome_mat', title: 'The Welcome Mat', category: 'history', unlockedBy: 'event',
    text: 'The Fellowship\'s great last project, left entirely open: five lamps, one invitation, and the freedom to decide what to do with it. They trusted whoever came next to be kind.' },
  { id: 'codex_ancient_signal', title: 'The Patient Signal', category: 'phenomenon', unlockedBy: 'event',
    text: 'A faint repeating signal from very old ruins, patient as a metronome. It seems to be waiting for someone to answer.' },
  { id: 'codex_singing_rifts', title: 'Singing Rifts', category: 'phenomenon', unlockedBy: { phenomenon: 'rift' },
    text: 'Folds in spacetime that hum in perfect fifths, like a choir in a very large cathedral. Navigators are advised to hum back; the rifts seem to appreciate the effort.' },
  { id: 'rift_lullaby', title: 'The Rift Lullaby', category: 'phenomenon', unlockedBy: 'event',
    text: 'Behind the Whispering Rift, a half-remembered lullaby carries on in a language nobody speaks. Hum along, and you will find you know the second verse.' },
  { id: 'codex_nebula_fog', title: 'Navigating Nebula Fog', category: 'phenomenon', unlockedBy: { phenomenon: 'nebula' },
    text: 'Glowing veils of gas that scatter sensors and soften every edge. Slow down, trust the pilot, and turn the cabin lights low to match the mood.' },
  { id: 'nebula_weather', title: 'Weather in the Veil', category: 'phenomenon', unlockedBy: 'event',
    text: 'The Veil\'s weather moves in long, soft fronts of colour, ranging from "pleasant" to "pleasant, with a chance of singing".' },
  { id: 'codex_pulsar_radio', title: 'Pulsar Radio Stations', category: 'phenomenon', unlockedBy: { phenomenon: 'pulsar' },
    text: 'Pulsars tick like cosmic clocks, and some are tuned to broadcast. The Choir\'s favourites play only low jazz and the weather.' },
  { id: 'codex_ion_surfing', title: 'Ion-Storm Surfing', category: 'phenomenon', unlockedBy: { phenomenon: 'ionstorm' },
    text: 'With a steady hand and a bit of nerve, a good pilot can ride the crest of an ion storm for free thrust. Do not tell the Meridian insurers.' },
  { id: 'codex_microjump', title: 'Wormhole Micro-Jumps', category: 'phenomenon', unlockedBy: { phenomenon: 'wormhole' },
    text: 'Small, unstable throats that hop a ship forward in a blink, if one finds their safe window. The Gate\'s great cousin, only wobblier and a bit shy.' },
  { id: 'codex_comet_harvest', title: 'Comet Tails and Cold Tea', category: 'phenomenon', unlockedBy: { phenomenon: 'comet' },
    text: 'Comet tails are full of fresh ice, fine for fuel and finer for tea. Harvesters say the tea tastes of winter mornings.' },
  { id: 'codex_singing_ice', title: 'The Singing Ice of the Cold Worlds', category: 'phenomenon', unlockedBy: { scan: 'planetType:ice' },
    text: 'Glaciers that sing faintly as they shift, producing long wandering notes. Vesperine pilgrims travel for centuries to listen.' },
  { id: 'codex_hot_springs', title: 'Restorative Springs and the Etiquette of Soaking', category: 'phenomenon', unlockedBy: { scan: 'feature:hot_springs' },
    text: 'Warm mineral springs that mend the weary and the morale-battered. Etiquette demands towels, small talk and absolutely no splashing.' },
  { id: 'codex_cloud_skimming', title: 'Skimming the Gas Giants', category: 'phenomenon', unlockedBy: { scan: 'planetType:gas' },
    text: 'Dipping low over a gas giant to scoop fuel is exhilarating and not for the faint-hearted. Hold on to your hat, and your pilot.' },
  { id: 'codex_shepherd_moons', title: 'Shepherd Moons and Ring Choreography', category: 'phenomenon', unlockedBy: 'event',
    text: 'Small moons herd the rings into neat bands, a celestial ballet held in place by gravity and patience. Watching them is a very good use of a quiet evening.' },

  // ---------------------------------------------------------------- TECH
  { id: 'tech_warp_coils', title: 'Warp Coils', category: 'tech', unlockedBy: null,
    text: 'Brass-wound coils that hum, glow teal and bend the fabric of space just enough to let a ship hop between stars. They like regular dusting.' },
  { id: 'tech_slide_rule', title: 'The Slide Rule', category: 'tech', unlockedBy: null,
    text: 'The Meridian Society\'s preferred navigational tool: wood, brass and an astonishing amount of arithmetic. It never needs charging.' },
  { id: 'tech_felt_charts', title: 'Felt-Tip Star Charts', category: 'tech', unlockedBy: null,
    text: 'Charts drawn by hand in twelve colours, then digitised and kept in a drawer because the drawers are prettier. A good chart is also a good gift.' },
  { id: 'tech_tuning_crystals', title: 'Tuning Crystals', category: 'tech', unlockedBy: { faction: 'vesperine' },
    text: 'Vesperine-grown crystals that store a note forever. Used in communications, music and the occasional particularly smug doorbell.' },
  { id: 'tech_vellum_sheets', title: 'Archive Vellum', category: 'tech', unlockedBy: { faction: 'archivists' },
    text: 'Self-indexing sheets that rewrite themselves in whichever language you read best. They are very proud of this, and say so in the margins.' },
  { id: 'tech_story_knots', title: 'Story Knots', category: 'tech', unlockedBy: { faction: 'drifters' },
    text: 'Knotted cords that remember one tale per knot, told by the hands that tie them. Handle with respect and never untie anything you have not been told.' },
  { id: 'tech_lantern_glass', title: 'Lantern Glass', category: 'tech', unlockedBy: { phenomenon: 'beacon' },
    text: 'A warm, clear glass that holds light for ages and hums near its kin. It appears to be grown rather than made, and nobody has found the seed.' },
  { id: 'charter_open_skies', title: 'The Charter of Open Skies', category: 'history', unlockedBy: 'event',
    text: 'A short, friendly charter signed by every people of the Reach: share the sky, say please, bring tea. It runs three paragraphs and has never been broken.' },
  { id: 'grand_harmonic', title: 'The Grand Harmonic', category: 'history', unlockedBy: 'event',
    text: 'Once in a lifetime, the Veil sings its whole song, and a guest is invited to hold one note. Most guests find the rest is the hardest part.' },
  { id: 'tea_summit', title: 'The Summit of Tea', category: 'history', unlockedBy: 'event',
    text: 'The first Concord-Quillari summit in which the tea came before the tariffs. It was, by every account, a very good summit.' },

  // ---------------------------------------------------------------- Added to cover EVENTS codex ids
  { id: 'codex_dock_festival', title: 'Dock Festival Customs', category: 'history', unlockedBy: 'event',
    text: 'When a port holds a festival, every visiting ship is expected to hang one decoration and eat one pastry. Declining either is considered a small, forgivable tragedy.' },
  { id: 'codex_form_77b', title: 'Concord Form 77-B and Its Discontents', category: 'history', unlockedBy: 'event',
    text: "A form so thorough that it has its own appendix, its own appendix's appendix, and an informal fan club. Filing it correctly is considered a minor act of heroism." },
  { id: 'codex_theremin', title: 'The Theremin, an Instrument You Do Not Touch', category: 'tech', unlockedBy: 'event',
    text: 'An old Terran instrument played by waving your hands near an antenna. The Vesperine consider it the single most civilised thing humans ever invented.' },
  { id: 'codex_slide_rule', title: 'Slide Rules and Why They Still Work', category: 'tech', unlockedBy: 'event',
    text: 'Wood, brass and logarithms: no batteries, no updates, no surprises. Meridian navigators swear by them, partly for the maths and partly for the feel.' },
  { id: 'codex_galley_bot', title: 'Galley Bot Gus-7: A Biography', category: 'species', unlockedBy: 'event',
    text: 'A cheerful galley robot with seven spatulas and one unshakeable opinion about toast. He has been with Halcyon longer than anyone can quite recall.' },
  { id: 'codex_ship_tea', title: 'Tea Aboard: A Brief Ritual', category: 'history', unlockedBy: 'event',
    text: 'At the end of every long watch, the crew gather in the lounge for tea, with no talk of business until the cups are empty. It is, quietly, what holds the ship together.' },

  // ---------------------------------------------------------------- Fix round 1: more entries
  { id: 'tamsin_vell', title: 'Captain Tamsin Vell', category: 'species', unlockedBy: { flag: 'rival_met' },
    text: 'A free-trader with a shiny ship, a loud laugh and an unshakable belief that she can beat anyone to anywhere. She has never once been right, and has never once minded.' },
  { id: 'distress_calls', title: 'Distress Calls of the Reach', category: 'history', unlockedBy: { mission: 'm_distress_medical' },
    text: 'Small, cheerful calls for help sent by settlers and haulers who would rather not trouble anyone. Meridian answers all of them, on principle and by the order of Director Calloway.' },
  { id: 'rescue_medal', title: 'The Meridian Rescue Medal', category: 'history', unlockedBy: { mission: 'm_distress_fuel' },
    text: 'A little enamel medal awarded to anyone who answers a call for help. It carries no privilege whatever, and is worn with fierce pride.' },
  { id: 'lamplight_festival', title: 'The Lamplight Festival', category: 'history', unlockedBy: { mission: 'm_festival_3_parade' },
    text: 'A yearly Quillari celebration in which a thousand paper lanterns are towed from Pennywhistle to Brightwater. It is slow, loud and joyful, and has never once arrived on time.' },
  { id: 'footnote_dispute', title: 'The Disputed Footnote', category: 'history', unlockedBy: { mission: 'm_dip_footnote_2' },
    text: 'A short footnote that two peoples claimed for different reasons and settled over two sheets of vellum. Historians call it the Reach\'s most civilised argument.' },
  { id: 'quiet_treaty', title: 'The Quiet Treaty', category: 'history', unlockedBy: { mission: 'm_dip_quiet_treaty_2' },
    text: 'An informal peace between a drifter habitat and a Vesperine choir, sealed with soft cloth and tuning crystals. The habitat now oils its hinges before every dinner.' },
  { id: 'pulsar_choir', title: 'The Pulsar Choir', category: 'place', unlockedBy: { star: 'neutron' },
    text: 'A ring of slow, patient pulsars that tick in near-unison. Vesperine mystics say they are keeping time for something enormous, and have not yet been told what.' },
  { id: 'vesper_veil', title: 'The Vesper Veil', category: 'place', unlockedBy: { faction: 'vesperine' },
    text: 'A gently glowing nebula where the Vesperine sing their cities into being. The gas is cold, harmless and faintly applauds when a ship passes through quietly.' },
  { id: 'brightwater_shoals', title: 'The Brightwater Shoals', category: 'place', unlockedBy: { visit: 'pennywhistle' },
    text: 'A crowded, cheerful scatter of trade stars where Quillari clans haggle across every lane. A rumour is worth more than a cargo, and a cargo is worth more than a promise.' },
  { id: 'quiet_rim', title: 'The Quiet Rim', category: 'place', unlockedBy: { visit: 'long_table' },
    text: 'The far edge of the survey, where drifter habitats wander between stars. Even the silence out here sounds like someone about to tell a story.' },
  { id: 'wickhaven', title: 'Wickhaven', category: 'place', unlockedBy: { visit: 'lantern_wick' },
    text: 'A modest orange star with an ice world and a very old lamp. It is where the first Lantern was found, and where the first hello was said.' },
  { id: 'marginalia', title: 'Marginalia', category: 'place', unlockedBy: { visit: 'archive_heart' },
    text: 'The Archive\'s innermost margin, where the librarians keep the questions nobody has asked. The Heart Vault is a quiet place, and it is waiting to be asked correctly.' },
  { id: 'tessitura_site', title: 'Tessitura', category: 'place', unlockedBy: { visit: 'tessitura' },
    text: 'A neutron star that ticks like a grandfather clock the size of a city. The fourth Lantern sits in its lee and keeps perfect time.' },
  { id: 'whispering_rift_site', title: 'The Whispering Rift', category: 'place', unlockedBy: { visit: 'whispering_rift' },
    text: 'A fold in space that hums a half-remembered lullaby. Navigators are advised to hum back, and to bring a blanket.' },
  { id: 'weathervane_storms', title: 'The Weathervane Storm', category: 'phenomenon', unlockedBy: { visit: 'weathervane' },
    text: 'A friendly ion storm that rearranges itself every few hours. The Vesperine choirs here are very patient, and the navigators very tired.' },
  { id: 'black_hole_candle', title: 'A Candle Beside a Black Hole', category: 'phenomenon', unlockedBy: { star: 'blackhole' },
    text: 'The sleeping black hole at Last Taper bends starlight into a slow halo around the fifth Lantern. It looks, from a distance, like a very large window with a very small candle in it.' },
  { id: 'binary_dawn', title: 'Binary Dawn', category: 'phenomenon', unlockedBy: { star: 'binary' },
    text: 'Two suns rising together paint every landscape in double shadows. Painters, poets and the occasional sunburnt navigator agree it is worth the squint.' },
  { id: 'red_dwarf_lights', title: 'Red-Dwarf Evenings', category: 'phenomenon', unlockedBy: { star: 'red' },
    text: 'Red stars give a long, warm twilight that lasts for weeks. The settlements beneath them have unusually good tea and unusually bad sleeping habits.' },
  { id: 'crystal_worlds', title: 'The Crystal Worlds', category: 'phenomenon', unlockedBy: { scan: 'planetType:crystal' },
    text: 'Planets grown of faceted stone, ringing faintly in the solar wind. Vesperine pilgrims call them the first instruments.' },
  { id: 'ocean_worlds', title: 'Ocean Worlds', category: 'phenomenon', unlockedBy: { scan: 'planetType:ocean' },
    text: 'Planets of warm, shallow seas and floating gardens, where the weather is a rumour and the sunsets last for hours.' },
  { id: 'jungle_worlds', title: 'Jungle Worlds', category: 'phenomenon', unlockedBy: { scan: 'planetType:jungle' },
    text: 'Planets so lush that the canopy hums, thick with life that has never seen a ship before and rather likes the look of this one.' },
  { id: 'lava_worlds', title: 'Lava Worlds', category: 'phenomenon', unlockedBy: { scan: 'planetType:lava' },
    text: 'Molten worlds of glowing rivers and basalt cliffs. The forge-folk say they are the warmest places in the galaxy, and the most honest.' },
  { id: 'ruins_ancient', title: 'Ancient Ruins', category: 'history', unlockedBy: { scan: 'feature:ruins' },
    text: 'Quiet remnants of earlier visitors, polite and strangely well-kept. Nobody has found a single sign of conflict, only of long, unhurried departures.' },
  { id: 'tech_meridian_beacons', title: 'Meridian Relay Buoys', category: 'tech', unlockedBy: null,
    text: 'Small, round buoys the Society leaves at every surveyed system, humming softly and reminding passing ships that someone was here before them, and was kind.' },

  // ---------------------------------------------------------------- Fix round 1: EVENTS-B ids
  { id: 'codex_cartographers_ship', title: "The Cartographer's Ship", category: 'place', unlockedBy: 'event',
    text: "A drifting survey ship still plotting its last chart in lamp-lit ink. Its crew left the pen uncapped, which every cartographer finds deeply moving." },
  { id: 'codex_pulsar_greeting', title: "The Pulsar Greeting", category: 'phenomenon', unlockedBy: 'event',
    text: "Some pulsars answer a polite hail by changing their rhythm for a single beat. Radio astronomers call it the shortest conversation in the galaxy and the most gracious." },
  { id: 'codex_comet_tumbleweed', title: "Comet Tumbleweeds", category: 'phenomenon', unlockedBy: 'event',
    text: "Loose knots of ice and dust that roll along magnetic lines like tumbleweeds in a very cold desert. They are harmless, fascinating, and excellent in tea." },
  { id: 'codex_wormhole_manners', title: "Wormhole Manners", category: 'phenomenon', unlockedBy: 'event',
    text: "Small wormholes are said to prefer a steady approach and a polite word. Ships that rush them wobble; ships that ask nicely are carried through." },
  { id: 'codex_frost_flowers', title: "Frost Flowers", category: 'phenomenon', unlockedBy: 'event',
    text: "Delicate feathers of ice that bloom overnight on cold worlds and chime when the wind touches them. They are gone by noon, and the children of the colonies leave out little saucers anyway." },
  { id: 'codex_old_buoys', title: "The Old Buoys", category: 'history', unlockedBy: 'event',
    text: "Weathered survey buoys of unknown make, still blinking patiently in the dark. Each one is stamped with an open eye, and each one is, remarkably, still on schedule." },
  { id: 'codex_lava_glass', title: "Lava Glass", category: 'tech', unlockedBy: 'event',
    text: "Dark, translucent glass cooled from molten flows and shaped by forge-folk into lenses, cups and windows. It holds heat beautifully and is said to remember the shape of the fire." },
  { id: 'codex_dune_script', title: "Dune Script", category: 'history', unlockedBy: 'event',
    text: "Long, looping writing drawn in the sand by the wind itself, or by someone patient. The characters change every night, and the message appears to be Hello again." },
  { id: 'codex_glass_fields', title: "The Glass Fields", category: 'place', unlockedBy: 'event',
    text: "Wide plains of fused sand, polished smooth by ancient storms, that reflect the sky so perfectly that walkers feel they are crossing the heavens. A famous spot for picnics and for losing hats." },
  { id: 'codex_deep_singers', title: "The Deep Singers", category: 'species', unlockedBy: 'event',
    text: "Gentle creatures of deep oceans who sing in long, resonant phrases that travel for hundreds of kilometres. Listening to them is said to cure homesickness, grumpiness and occasionally hiccups." },
  { id: 'codex_canopy_lights', title: "Canopy Lights", category: 'phenomenon', unlockedBy: 'event',
    text: "On jungle worlds the treetops glow in slow, drifting waves of green and gold. Naturalists believe the trees are talking; the trees, asked politely, decline to comment." },
  { id: 'codex_orchard_tractors', title: "The Orchard Tractors", category: 'tech', unlockedBy: 'event',
    text: "Patient farm-robots that tend abandoned orchards on lonely worlds, still harvesting for a market that closed long ago. They are delighted to give visitors fruit and a polite lecture on pruning." },
  { id: 'codex_hollowell', title: "Hollowell", category: 'place', unlockedBy: 'event',
    text: "A small, cheerful settlement built inside a dormant crater, known for its singing wells and its excellent rhubarb. Visitors are told the wells are haunted, and the haunting is mostly harmonies." },
  { id: 'codex_crater_letters', title: "Crater Letters", category: 'history', unlockedBy: 'event',
    text: "Messages spelled in stones inside old craters by travellers of every era, each addressed to whoever comes next. Some are jokes, some are poems, and one just says Mind the step." },
  { id: 'codex_ore_claims', title: "Ore Claims and Courtesy", category: 'history', unlockedBy: 'event',
    text: "Miners mark a claim with a ribbon and a note, and the custom is that no one touches a marked vein for a year. In all recorded history, the custom has held without a single lock." },
  { id: 'codex_crystal_bloom', title: "Crystal Bloom", category: 'phenomenon', unlockedBy: 'event',
    text: "Once a decade, crystal worlds flower: facets split into delicate petals that ring in the starlight. Pilgrims attend with tuning forks and good manners." },
  { id: 'codex_acid_rain', title: "Acid Rain Etiquette", category: 'phenomenon', unlockedBy: 'event',
    text: "Toxic worlds shower acid, politely, on a schedule. Locals carry umbrellas of ceramic and the habit of looking up before they speak." },
  { id: 'codex_floating_gardens', title: "Floating Gardens", category: 'place', unlockedBy: 'event',
    text: "Terraced gardens drifting on the thermals of gas giants, tended by cloud-farmers who wave at passing ships. The tomatoes are famous, and so is the hospitality." },
  { id: 'codex_ring_ice', title: "Ring Ice", category: 'phenomenon', unlockedBy: 'event',
    text: "The icy dust in planetary rings is the purest water in the Reach and scoops up as easily as snow. Navigators claim it makes the best tea, and the best arguments about tea." },
  { id: 'codex_survey_stakes', title: "Survey Stakes", category: 'tech', unlockedBy: 'event',
    text: "Small brass stakes left by the Society and by those before it, marking chartered ground. A stake with the open-eye stamp is older than anything in the Society's archive and has never once rusted." },
  { id: 'codex_aurora_fields', title: "Aurora Fields", category: 'phenomenon', unlockedBy: 'event',
    text: "Sheets of living light that unfold across the poles of certain worlds. Aurora-beings gather here to compose, and visitors are asked to hum quietly if they must hum at all." },
  { id: 'codex_dust_postcards', title: "Dust Postcards", category: 'history', unlockedBy: 'event',
    text: "Messages drawn in settled dust on abandoned ships and stations by passing travellers, with dates and tiny cheerful drawings. Archivists treat them as the best primary sources in existence." },
  { id: 'codex_sandships', title: "Sandships", category: 'tech', unlockedBy: 'event',
    text: "Wind-driven vessels that sail desert seas on great wheels of woven reed. Their captains are fiercely proud, and will race you for the price of a cup of tea." },
  { id: 'codex_seedling_court', title: "The Seedling Court", category: 'species', unlockedBy: 'event',
    text: "A grove of young trees that holds mock trials on certain evenings, with insects as witnesses and a very old oak as judge. The sentences are always plant something." },
  { id: 'codex_tide_tables', title: "Tide Tables of Two Moons", category: 'tech', unlockedBy: 'event',
    text: "Tables kept by harbour-keepers on worlds with more than one moon, tracking the intricate dance of high and low water. Learning to read them takes years; ignoring them takes one good soaking." },
  { id: 'codex_lantern_syntax', title: "Lantern Syntax", category: 'phenomenon', unlockedBy: 'event',
    text: "The Lanterns blink in a grammar of long and short pulses, with tenses for was, is and if-you-like. Linguists say it reads, unmistakably, like a letter written by a host." },

  // ---------------------------------------------------------------- Fix round 2: scans / landings / phenomena
  { id: "codex_scan_geyser_gardens", title: "Geyser Gardens", category: "place", unlockedBy: "event",
    text: "Tidy rows of geysers that erupt in turn, watering terraces of hardy moss. Whoever planned them clearly liked a good rota." },
  { id: "codex_scan_ice_lake", title: "The Ice Lake", category: "place", unlockedBy: "event",
    text: "A frozen lake so clear that sunlight seems to go all the way to the bottom. Skaters are advised to bring a hat and humility." },
  { id: "codex_scan_ice_ore", title: "Ice-Bound Ore", category: "place", unlockedBy: "event",
    text: "Veins of bright metal sealed in blue ice, shining like jam in a jar. Miners nickname the seams after their grandmothers." },
  { id: "codex_scan_ice_curtain", title: "The Ice Curtain", category: "phenomenon", unlockedBy: "event",
    text: "Sheets of frost that hang in the air above cold worlds, tinkling as they sway. It sounds, to the careful listener, like someone laughing very quietly." },
  { id: "codex_scan_cairns", title: "Stone Cairns", category: "history", unlockedBy: "event",
    text: "Neat stacks of stones left on the high ground of quiet worlds. Each one points toward the next, and the last points politely at you." },
  { id: "codex_scan_lava_forge_ruins", title: "Forge Ruins", category: "history", unlockedBy: "event",
    text: "Cold furnaces and anvils of a craft that valued patience over haste. The tongs are still hanging by the door." },
  { id: "codex_scan_lava_seam", title: "The Lava Seam", category: "place", unlockedBy: "event",
    text: "A glowing crack in the rock where the planet's warmth leaks out in a gentle orange smile. Hot, harmless from a distance, and very good for toast." },
  { id: "codex_scan_lava_baths", title: "Lava Baths", category: "place", unlockedBy: "event",
    text: "Natural pools warmed by the deep fire, ringed by heat-glass benches. Locals say a soak here fixes aching joints and wounded pride." },
  { id: "codex_scan_lava_hum", title: "The Lava Hum", category: "phenomenon", unlockedBy: "event",
    text: "A low, steady note that rises from molten worlds, like a cello tuned to the core of the planet. Engineers say it improves their moods; engines say nothing." },
  { id: "codex_scan_dune_ore", title: "Dune Ore", category: "place", unlockedBy: "event",
    text: "Rich metal grains swept into ripples by the wind, glittering at dusk. Sandship crews skim it into buckets and call it a day." },
  { id: "codex_scan_obelisk", title: "The Obelisk", category: "history", unlockedBy: "event",
    text: "A single smooth pillar standing alone in the desert, humming faintly when touched. It bears no writing, only a small carved open eye near the base." },
  { id: "codex_scan_desert_hum", title: "The Desert Hum", category: "phenomenon", unlockedBy: "event",
    text: "A deep note rolling across dunes at dawn, as if the sand were thinking aloud. It stops the moment anyone tries to record it, which is very polite." },
  { id: "codex_scan_oasis", title: "The Oasis", category: "place", unlockedBy: "event",
    text: "A ring of green around a spring in the heart of the dunes, shaded by cheerful palms. A tin cup hangs by the water with a note: please refill." },
  { id: "codex_scan_ocean_aurora", title: "Ocean Aurora", category: "phenomenon", unlockedBy: "event",
    text: "Lights that glide across the sea at night, mirrored in the waves so the sky seems to be swimming. Fishers drop their nets and simply watch." },
  { id: "codex_scan_drowned_spire", title: "The Drowned Spire", category: "history", unlockedBy: "event",
    text: "A tall tower rising from the shallows, its upper windows still lit by some patient inner lamp. The tide laps the door like a hesitant guest." },
  { id: "codex_scan_nodules", title: "Sea-Floor Nodules", category: "place", unlockedBy: "event",
    text: "Round, dark stones scattered along the ocean bed like potatoes. They are full of useful metals, and rather shy." },
  { id: "codex_scan_sonar_hum", title: "The Sonar Hum", category: "phenomenon", unlockedBy: "event",
    text: "Deep sea tones that bounce between continents, a conversation in one long sentence. Marine biologists have been trying to reply for decades." },
  { id: "codex_scan_jungle_stairs", title: "The Jungle Stairs", category: "history", unlockedBy: "event",
    text: "Broad stone steps climbing through the canopy, worn smooth by many careful feet. The railings are carved with leaves that nod in the breeze." },
  { id: "codex_scan_jungle_baths", title: "Jungle Baths", category: "place", unlockedBy: "event",
    text: "Warm pools hidden in the roots of giant trees, ringed with ferns and the occasional curious frog. Strictly towels and small talk." },
  { id: "codex_scan_jungle_cliffs", title: "The Jungle Cliffs", category: "place", unlockedBy: "event",
    text: "Green walls draped in flowers and waterfalls, with hanging gardens nobody planted. The view is so good that photographers cry." },
  { id: "codex_scan_terran_town", title: "A Quiet Terran Town", category: "place", unlockedBy: "event",
    text: "A cluster of rooftops with chimneys, gardens and a very optimistic bandstand. Everyone waves, and nobody asks how long you are staying." },
  { id: "codex_scan_terran_aurora", title: "Terran Aurora", category: "phenomenon", unlockedBy: "event",
    text: "Ribbons of green and rose dancing over gentle hills, so soft that dogs howl approvingly. Ideal for picnics and unplanned proposals." },
  { id: "codex_scan_quarry", title: "The Old Quarry", category: "place", unlockedBy: "event",
    text: "A terraced pit of pale stone, abandoned in good order and swept every spring by someone unseen. The stones are cut so cleanly they could be bread." },
  { id: "codex_scan_barren_dome", title: "The Dome on the Plain", category: "history", unlockedBy: "event",
    text: "A smooth white dome on a bare plain, still airtight and faintly warm. Inside, the chairs are arranged in a circle, as if for a meeting that ran long." },
  { id: "codex_scan_barren_hum", title: "The Barren Hum", category: "phenomenon", unlockedBy: "event",
    text: "A faint note that rises from lifeless rock when the sun sets. Geologists blame the crystals; the crystals decline to comment." },
  { id: "codex_scan_warm_patch", title: "The Warm Patch", category: "place", unlockedBy: "event",
    text: "A circle of unexpectedly cosy ground on an otherwise frozen world. Surveyors rest their feet there and write their best reports." },
  { id: "codex_scan_crystal_vein", title: "The Crystal Vein", category: "place", unlockedBy: "event",
    text: "A ribbon of faceted stone running through the bedrock, glowing from within. It rings when struck softly, with a tone like a very small bell." },
  { id: "codex_scan_crystal_ruin", title: "Crystal Ruins", category: "history", unlockedBy: "event",
    text: "Half-grown temples of living crystal, abandoned mid-song. The Vesperine say the song is still going on, just very slowly." },
  { id: "codex_scan_crystal_hum", title: "The Crystal Hum", category: "phenomenon", unlockedBy: "event",
    text: "A sustained chord from crystal worlds, resonating in the hull plates and in the teeth. Pleasant, and impossible to hum along with." },
  { id: "codex_scan_toxic_ruin", title: "Ruins in the Fog", category: "history", unlockedBy: "event",
    text: "Elegant pavilions half-swallowed by drifting green haze, still standing in perfect proportion. The doors are left open, for the visitors who can breathe." },
  { id: "codex_scan_toxic_ore", title: "Toxic Ore", category: "place", unlockedBy: "event",
    text: "Brightly coloured metals in the sludge, safe to collect with the right gloves and the wrong opinions. Miners wear aprons and sing." },
  { id: "codex_scan_toxic_aurora", title: "Toxic Aurora", category: "phenomenon", unlockedBy: "event",
    text: "Violet and green lights that flicker through acid clouds, beautiful and thoroughly unsafe to touch. A fine thing to watch through a thick window." },
  { id: "codex_scan_gas_eye", title: "The Great Eye", category: "phenomenon", unlockedBy: "event",
    text: "A calm vortex in the clouds of a gas giant, wide as a continent and quiet as a hush. Skimmers say the lighting inside is excellent." },
  { id: "codex_scan_gas_aurora", title: "Giant's Aurora", category: "phenomenon", unlockedBy: "event",
    text: "Immense curtains of light that wrap a gas giant's poles like a scarf. Aurora-beings are said to knit them, and to enjoy it." },
  { id: "codex_scan_gas_hum", title: "The Giant's Hum", category: "phenomenon", unlockedBy: "event",
    text: "A deep thrum from the storm bands of a gas giant, felt in the ribs more than the ears. Pilots call it the planet purring." },
  { id: "codex_land_mining_camp", title: "The Mining Camp", category: "place", unlockedBy: "event",
    text: "A tidy collection of huts, sluices and notice boards left by cheerful prospectors. The board announces the weekly quiz, and the answers are all tea." },
  { id: "codex_land_singing_vein", title: "The Singing Vein", category: "phenomenon", unlockedBy: "event",
    text: "A seam of ore that hums when light touches it, ringing out a note that carries for miles. Miners say it is lucky; so do the bats." },
  { id: "codex_land_adit", title: "The Old Adit", category: "place", unlockedBy: "event",
    text: "A mine entrance shored up with careful timbers, still dry and lit by tiny lamps that never go out. A sign reads: mind your head, and your manners." },
  { id: "codex_land_bath_house", title: "The Bath House", category: "place", unlockedBy: "event",
    text: "A stone bathhouse built over a hot spring, with benches, hooks for hats, and a sign that says everyone is welcome. Everyone seems to have taken it at its word." },
  { id: "codex_land_geyser_clock", title: "The Geyser Clock", category: "tech", unlockedBy: "event",
    text: "A great geyser that erupts at precise intervals, ringed by dials and brass markers. Travellers set their watches by it, and it is never wrong." },
  { id: "codex_land_aurora_picnic", title: "The Aurora Picnic", category: "history", unlockedBy: "event",
    text: "A long table laid on a hilltop beneath dancing lights, with places set for dozens. Nobody knows who was invited; the cake is still good." },
  { id: "codex_land_aurora_photos", title: "The Aurora Photographs", category: "history", unlockedBy: "event",
    text: "Plates of glass left by long-ago visitors, each showing the same sky under different seasons. A note on the back says: we were here, and it was lovely." },
  { id: "codex_land_tea_house", title: "The Tea House", category: "place", unlockedBy: "event",
    text: "A little pavilion with low tables, tidy cups and a kettle that is somehow still warm. A guest book beside the door has a recent entry in a very old hand." },
  { id: "codex_land_mosaic", title: "The Mosaic Floor", category: "history", unlockedBy: "event",
    text: "A vast tiled floor depicting the Reach's stars, laid by patient hands with every colour of stone. The Lanterns are marked in gold." },
  { id: "codex_land_old_lift", title: "The Old Lift", category: "tech", unlockedBy: "event",
    text: "A glass elevator descending into a hollow hillside, still polite and still working. The buttons are labelled with stars instead of numbers." },
  { id: "codex_land_buried_antenna", title: "The Buried Antenna", category: "tech", unlockedBy: "event",
    text: "A tall mast half-buried in the dunes, still pointing at a particular patch of sky. Whoever left it listening is long gone, but it has not given up." },
  { id: "codex_land_signal_choir", title: "The Signal Choir", category: "phenomenon", unlockedBy: "event",
    text: "A ring of antennae that hum in parallel, producing a chord that rolls across the plain at dusk. Visitors who stand in the centre report feeling warmly greeted." },
  { id: "codex_phen_nebula_balloon", title: "Nebula Balloons", category: "phenomenon", unlockedBy: "event",
    text: "Soft bubbles of glowing gas that drift through nebulae like lazy jellyfish. They pop, politely, with a tiny note of apology." },
  { id: "codex_phen_star_nursery", title: "The Star Nursery", category: "phenomenon", unlockedBy: "event",
    text: "A crowd of young stars wrapped in dust like babies in blankets. The Vesperine sing lullabies here, and the dust gently hums along." },
  { id: "codex_phen_tumbling_library", title: "The Tumbling Library", category: "history", unlockedBy: "event",
    text: "A shattered Archive barge, its books tumbling slowly through the asteroids in perfect order. Archivists drift by with nets, clucking sadly and happily at once." },
  { id: "codex_phen_rock_garden", title: "The Rock Garden", category: "place", unlockedBy: "event",
    text: "A neat arrangement of asteroids raked into patterns by something patient, in the middle of nowhere. The rakes are still leaning against a boulder." },
  { id: "codex_phen_comet_postbox", title: "The Comet Postbox", category: "tech", unlockedBy: "event",
    text: "A tiny red postbox bolted to a comet's nucleus, collecting letters at every orbit. Postmasters swear that most of them are delivered." },
  { id: "codex_phen_aurora_duet", title: "The Aurora Duet", category: "phenomenon", unlockedBy: "event",
    text: "Two aurora-beings sharing a melody in light, alternating phrases like old friends. Listeners learn to wait for the end, which comes with a bow." },
  { id: "codex_phen_greenhouse", title: "The Floating Greenhouse", category: "place", unlockedBy: "event",
    text: "A glass greenhouse adrift among the asteroids, full of well-watered tomatoes and one slightly bewildered gnome. It is operated by a very friendly robot." },
  { id: "codex_phen_toll_booth", title: "The Toll Booth in the Void", category: "phenomenon", unlockedBy: "event",
    text: "A neat booth beside the wormhole, staffed by an optimistic automaton collecting no tolls at all. It will cheerfully explain why." },
  { id: "codex_stipend_telegrams", title: "Stipend Telegrams", category: "history", unlockedBy: "event",
    text: "Brief, warm telegrams from the Society, arriving with the monthly allowance. They are always signed with a flourish, and always begin: dear captain, mind the tea." },

  { id: 'vell_marigold', title: 'The Marigold', category: 'tech', unlockedBy: { mission: 'm_rival_2_tied_race' },
    text: 'Captain Vell\'s ship: a polished free-trader painted the colour of a daffodil, with a tea urn bolted to the bridge. It is slightly faster than Halcyon, and Vell never lets you forget it.' },
  { id: 'reach_regatta', title: 'The Reach Regatta', category: 'history', unlockedBy: { flag: 'rival_beaten' },
    text: 'A friendly, weapons-free race held between traders of the Reach, with a purse, a ribbon and a great deal of tea. Winners are announced at dinner, and the losers insist on being gracious.' },
  { id: 'shipyard_commissions', title: 'Shipyard Commissions', category: 'history', unlockedBy: { mission: 'm_comm_hull_plates' },
    text: 'Big jobs posted by the Reach\'s yards: parts in, scrip out, and no hurry unless you let there be one. A completed commission is considered a mark of a trustworthy captain.' },
  { id: 'great_convergence', title: 'The Great Convergence', category: 'history', unlockedBy: { flag: 'convergence_held' },
    text: 'The first meeting at which all five peoples of the Reach sat at one round table. It adjourned for pastries, and has been called, ever since, the most successful summit of the age.' },
  { id: 'silence_stone_lore', title: 'The Silence-Stone', category: 'tech', unlockedBy: 'event',
    text: 'A smooth grey Vesperine stone that hums only in perfect quiet. The Vesperine give it to those who have chosen silence on purpose, and to nobody else.' },
];
